-- Wrapped with production-fixture.sql in one transaction by the disposable runner. No external HTTP.
create temporary table production_assertions(name text primary key);
grant insert on production_assertions to authenticated,service_role;
create function pg_temp.prod_check(ok boolean,name text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'Production assertion failed: %',name;end if;
 insert into production_assertions values(name);end $$;
select set_config('test.prod.homo_history',(select jsonb_agg(to_jsonb(o) order by id)::text from public.fiscal_operations o where environment='homologation'),false);
select set_config('test.prod.homo_counters',(select coalesce(jsonb_agg(to_jsonb(c) order by issuer_cnpj,municipality,series)::text,'[]') from private.dps_counters c where environment='homologation'),false);
set role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.prod.actor'))::text,false);
select pg_temp.prod_check((public.production_report_status(current_setting('test.prod.company')::uuid)->>'ready')::boolean,'owner sees bound production access');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002"}',false);
select pg_temp.prod_check(public.production_report_status(current_setting('test.prod.company')::uuid) is null,'foreign owner cannot inspect production access');
do $$ begin
 begin perform public.record_production_readiness_with_local_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('c',64),404,repeat('f',64));raise exception 'Client local proof';exception when insufficient_privilege then perform pg_temp.prod_check(true,'client cannot record local generator proof');end;
 begin perform public.reserve_production_check(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid);raise exception 'Direct production probe';exception when insufficient_privilege then perform pg_temp.prod_check(true,'production probe is server only');end;
 begin perform public.store_fiscal_danfse(current_setting('test.prod.actor')::uuid,gen_random_uuid(),'production',repeat('1',50),'',repeat('d',64));raise exception 'Client PDF injection';exception when insufficient_privilege then perform pg_temp.prod_check(true,'client cannot upload DANFSe');end;
 begin perform * from private.fiscal_production_readiness;raise exception 'Private readiness exposed';exception when insufficient_privilege then perform pg_temp.prod_check(true,'private access proof hidden');end;
end $$;
reset role;
delete from private.fiscal_production_readiness where company_id=current_setting('test.prod.company')::uuid;
set role service_role;
do $$ begin
 begin perform public.reserve_production_check('00000000-0000-4000-8000-000000000002',current_setting('test.prod.company')::uuid);raise exception 'Foreign probe';exception when insufficient_privilege then perform pg_temp.prod_check(true,'probe actor ownership enforced');end;
 begin perform public.enqueue_report_fiscal_production(current_setting('test.prod.actor')::uuid,current_setting('test.prod.review')::uuid,current_setting('test.prod.review_hash'),gen_random_uuid(),true);raise exception 'Production without proof';exception when object_not_in_prerequisite_state then perform pg_temp.prod_check(true,'homologation proof cannot unlock production queue');end;
 begin perform public.store_official_danfse_contract('production','https://adn.producaorestrita.nfse.gov.br/danfse/swagger/v1/swagger.json',repeat('d',64),'{"paths":{"/{chaveAcesso}":{"get":{}}}}');raise exception 'Cross environment contract';exception when invalid_parameter_value then perform pg_temp.prod_check(true,'DANFSe contract origin pinned by environment');end;
end $$;
select pg_temp.prod_check(not public.record_production_readiness(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('e',64),404),'contract hash bound to live capture');
select pg_temp.prod_check(not public.record_production_readiness(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('c',64),null),'missing HTTP cannot record readiness');
select pg_temp.prod_check(public.record_production_readiness(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('c',64),404),'production proof records actual HTTP');
reset role;
select pg_temp.prod_check(not private.production_company_ready(current_setting('test.prod.company')::uuid),'retired API-only proof does not release production');
set role service_role;
select pg_temp.prod_check(not public.record_production_readiness_with_local_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('c',64),404,repeat('f',64)),'unknown local specification rejected');
select pg_temp.prod_check(not public.record_production_readiness_with_local_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('e',64),404,'1265f403aedcdc5f08b3049dcc18a15c2bc155f51afccf3d12690fef2f4fb0ff'),'local generation cannot bypass captured SEFIN contract');
select pg_temp.prod_check(public.record_production_readiness_with_local_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.company')::uuid,current_setting('test.prod.certificate')::uuid,current_setting('test.prod.profile_hash'),repeat('c',64),404,'1265f403aedcdc5f08b3049dcc18a15c2bc155f51afccf3d12690fef2f4fb0ff'),'pinned local generator records bound production proof');
reset role;
select pg_temp.prod_check(private.production_company_ready(current_setting('test.prod.company')::uuid),'local proof and own fiscal guards release review');
set role service_role;

do $$ begin
 begin perform public.enqueue_report_fiscal_production(current_setting('test.prod.actor')::uuid,current_setting('test.prod.review')::uuid,current_setting('test.prod.review_hash'),gen_random_uuid(),false);raise exception 'No delivery consent';exception when object_not_in_prerequisite_state then perform pg_temp.prod_check(true,'real delivery consent required');end;
end $$;
select set_config('test.prod.batch',public.enqueue_report_fiscal_production(current_setting('test.prod.actor')::uuid,current_setting('test.prod.review')::uuid,current_setting('test.prod.review_hash'),gen_random_uuid(),true)->>'id',false);
select pg_temp.prod_check((public.enqueue_report_fiscal_production(current_setting('test.prod.actor')::uuid,current_setting('test.prod.review')::uuid,current_setting('test.prod.review_hash'),gen_random_uuid(),true)->>'id')=current_setting('test.prod.batch'),'confirmed report retry returns same batch');
reset role;
select pg_temp.prod_check((select count(*)=2 from public.fiscal_operations where batch_id=current_setting('test.prod.batch')::uuid and environment='production'),'two exact rows create two production operations');
select pg_temp.prod_check(exists(select 1 from public.invoice_email_batches where batch_id=current_setting('test.prod.batch')::uuid),'delivery enrollment commits with fiscal confirmation');
select pg_temp.prod_check((select count(*)=2 from private.fiscal_source_reservations where environment='production'),'source claims separated from homologation');
select pg_temp.prod_check((select count(*)=0 from private.dps_counters where environment='production'),'queue consent alone cannot reserve real numbers');
set role service_role;
select pg_temp.prod_check((select count(*)=0 from public.claim_fiscal_jobs(current_setting('test.prod.tenant')::uuid,1,false) j where j->>'environment'='production'),'old fiscal worker cannot claim production');
select set_config('test.prod.claim',j::text,false) from public.claim_fiscal_jobs_for_environment('production',current_setting('test.prod.tenant')::uuid,1,false) j;
reset role;
delete from public.fiscal_access_checks where company_id=current_setting('test.prod.company')::uuid and environment='production';
set role service_role;
select pg_temp.prod_check(public.reserve_fiscal_identity((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,current_setting('test.prod.certificate')::uuid) is null,'homologation transport cannot reserve production identity');
select pg_temp.prod_check(not public.record_fiscal_transport((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,current_setting('test.prod.certificate')::uuid),'old transport helper cannot unlock production');
select pg_temp.prod_check(public.record_fiscal_environment_transport((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,current_setting('test.prod.certificate')::uuid,404),'production worker records actual proof under lease');
select set_config('test.prod.identity',public.reserve_fiscal_identity((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,current_setting('test.prod.certificate')::uuid)::text,false);
select pg_temp.prod_check(current_setting('test.prod.identity')::jsonb->>'number'='1','production has independent first sequence');
select pg_temp.prod_check(not public.begin_fiscal_send_traced((current_setting('test.prod.claim')::jsonb->>'id')::uuid,gen_random_uuid(),current_setting('test.prod.certificate')::uuid,'synthetic','SYNTHETIC CERTIFICATE'),'stale lease cannot start production POST');
select pg_temp.prod_check(public.begin_fiscal_send_traced((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,current_setting('test.prod.certificate')::uuid,'SYNTHETIC ORIGINAL ONLY '||(current_setting('test.prod.identity')::jsonb->>'id'),'BEGIN CERTIFICATE synthetic only'),'one durable production intent');
select pg_temp.prod_check(not public.begin_fiscal_send_traced((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,current_setting('test.prod.certificate')::uuid,'SYNTHETIC ORIGINAL ONLY '||(current_setting('test.prod.identity')::jsonb->>'id'),'BEGIN CERTIFICATE synthetic only'),'second production POST denied');
select pg_temp.prod_check(public.finish_fiscal_attempt_traced((current_setting('test.prod.claim')::jsonb->>'id')::uuid,(current_setting('test.prod.claim')::jsonb->>'lease_token')::uuid,'authorized',null,repeat('2',50),'SYNTHETIC DATABASE STATE ONLY NFS'||repeat('2',50)||' '||(current_setting('test.prod.identity')::jsonb->>'id')),'trusted synthetic completion persists production document');
select pg_temp.prod_check(public.fiscal_xml_snapshot_for_diagnostic(current_setting('test.prod.actor')::uuid,(current_setting('test.prod.claim')::jsonb->>'id')::uuid)->>'id'=current_setting('test.prod.identity')::jsonb->>'id','production diagnostic reads original own snapshot');
select pg_temp.prod_check(public.fiscal_xml_snapshot_for_diagnostic('00000000-0000-4000-8000-000000000002',(current_setting('test.prod.claim')::jsonb->>'id')::uuid) is null,'production diagnostic rejects foreign actor');
select set_config('test.prod.email',public.claim_invoice_email_for_environment('production',current_setting('test.prod.tenant')::uuid)::text,false);
select pg_temp.prod_check(current_setting('test.prod.email')::jsonb->>'environment'='production','production email claim binds original fiscal environment');
select pg_temp.prod_check(public.claim_invoice_email(current_setting('test.prod.tenant')::uuid) is null,'old email worker cannot claim real delivery');
select pg_temp.prod_check(public.release_invoice_document_preparation((current_setting('test.prod.email')::jsonb->>'id')::uuid,(current_setting('test.prod.email')::jsonb->>'token')::uuid,'danfse_unavailable'),'missing PDF releases preparation before send intent');
reset role;
select pg_temp.prod_check((select attempts=0 and status='queued' from public.invoice_email_deliveries where id=(current_setting('test.prod.email')::jsonb->>'id')::uuid),'PDF failure consumes no email attempt');
select pg_temp.prod_check((select count(*)=0 from private.invoice_email_attempts where delivery_id=(current_setting('test.prod.email')::jsonb->>'id')::uuid),'PDF failure consumes no provider quota');
update public.invoice_email_deliveries set next_run_at=now() where id=(current_setting('test.prod.email')::jsonb->>'id')::uuid;
select set_config('test.prod.document',id::text,false) from public.fiscal_documents where operation_id=(current_setting('test.prod.claim')::jsonb->>'id')::uuid;
select set_config('test.prod.pdf',encode(convert_to('%PDF-1.7'||chr(10)||repeat('SYNTHETIC ONLY ',12)||chr(10)||'%%EOF'||chr(10),'UTF8'),'base64'),false);
set role service_role;
do $$ begin
 begin perform public.danfse_document_source('00000000-0000-4000-8000-000000000002',current_setting('test.prod.document')::uuid);raise exception 'Foreign DANFSe';exception when insufficient_privilege then perform pg_temp.prod_check(true,'known document id does not leak another tenant PDF');end;
 begin perform public.store_fiscal_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid,'homologation',repeat('2',50),current_setting('test.prod.pdf'),repeat('d',64));raise exception 'Cross environment PDF';exception when insufficient_privilege then perform pg_temp.prod_check(true,'PDF cannot bind across environment');end;
end $$;
select pg_temp.prod_check(public.danfse_document_source(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid)->>'generator'='nt008-1.02-rex-v1','uncached authorized document exposes local generator version');
select pg_temp.prod_check(public.danfse_document_source(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid)->'original'->>'xml' like 'SYNTHETIC ORIGINAL ONLY %','original signed DPS snapshot returned only to server owner');
reset role;
select set_config('test.prod.original',signed_dps_xml,false) from private.fiscal_execution where operation_id=(current_setting('test.prod.claim')::jsonb->>'id')::uuid;
update private.fiscal_execution set signed_dps_xml='TAMPERED SYNTHETIC' where operation_id=(current_setting('test.prod.claim')::jsonb->>'id')::uuid;
set role service_role;
select pg_temp.prod_check(public.danfse_document_source(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid) is null,'tampered original DPS fails closed before rendering');
reset role;
update private.fiscal_execution set signed_dps_xml=current_setting('test.prod.original') where operation_id=(current_setting('test.prod.claim')::jsonb->>'id')::uuid;
update public.company_certificates set status='revoked' where id=current_setting('test.prod.certificate')::uuid;
set role service_role;
select pg_temp.prod_check(public.danfse_document_source(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid)->'original'->>'certificatePem'='BEGIN CERTIFICATE synthetic only','authorized PDF source does not require current private A1');
reset role;
update public.company_certificates set status='active' where id=current_setting('test.prod.certificate')::uuid;
set role service_role;
select pg_temp.prod_check(not public.store_fiscal_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid,'production',repeat('2',50),current_setting('test.prod.pdf'),repeat('e',64)),'PDF requires actual source contract hash');
select pg_temp.prod_check(public.store_fiscal_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid,'production',repeat('2',50),current_setting('test.prod.pdf'),repeat('d',64)),'official-channel PDF cache persists bound authorized document');
select pg_temp.prod_check(public.store_fiscal_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid,'production',repeat('2',50),current_setting('test.prod.pdf'),repeat('d',64)),'same PDF write is idempotent');
select pg_temp.prod_check(not public.store_fiscal_danfse(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid,'production',repeat('2',50),encode(convert_to('%PDF-'||repeat('DIFFERENT SYNTHETIC ',12),'UTF8'),'base64'),repeat('d',64)),'cached PDF is immutable');
select pg_temp.prod_check(public.danfse_document_source(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid)->>'sha256'=encode(sha256(decode(current_setting('test.prod.pdf'),'base64')),'hex'),'retrieval returns matching PDF hash');
select set_config('test.prod.email',public.claim_invoice_email_for_environment('production',current_setting('test.prod.tenant')::uuid)::text,false);
do $$ begin
 begin perform public.begin_invoice_email((current_setting('test.prod.email')::jsonb->>'id')::uuid,(current_setting('test.prod.email')::jsonb->>'token')::uuid,array['brevo'],'seller@example.com','notas@example.com',true,repeat('e',64));raise exception 'Production marked as test';exception when invalid_parameter_value then perform pg_temp.prod_check(true,'production delivery cannot disguise test mode');end;
end $$;
select pg_temp.prod_check(public.begin_invoice_email((current_setting('test.prod.email')::jsonb->>'id')::uuid,(current_setting('test.prod.email')::jsonb->>'token')::uuid,array['brevo'],'seller@example.com','notas@example.com',false,repeat('e',64))->>'provider'='brevo','confirmed production delivery acquires single provider intent');
select pg_temp.prod_check(not public.release_invoice_document_preparation((current_setting('test.prod.email')::jsonb->>'id')::uuid,(current_setting('test.prod.email')::jsonb->>'token')::uuid,'danfse_unavailable'),'PDF retry cannot clear an email send intent');
reset role;
update private.nfse_api_contracts set sha256=repeat('f',64) where environment='production';
select pg_temp.prod_check(not private.production_company_ready(current_setting('test.prod.company')::uuid),'contract replacement invalidates production proof');
update private.nfse_api_contracts set sha256=repeat('c',64) where environment='production';
update public.company_certificates set status='revoked' where id=current_setting('test.prod.certificate')::uuid;
select pg_temp.prod_check(not private.production_company_ready(current_setting('test.prod.company')::uuid),'certificate revocation invalidates production proof');
set role service_role;
select pg_temp.prod_check(public.danfse_document_source(current_setting('test.prod.actor')::uuid,current_setting('test.prod.document')::uuid)->>'pdf' is not null,'cached authorized PDF survives certificate replacement');
reset role;
select pg_temp.prod_check((select jsonb_agg(to_jsonb(o) order by id)::text from public.fiscal_operations o where environment='homologation')=current_setting('test.prod.homo_history'),'historical homologation operations preserved byte for byte');
select pg_temp.prod_check((select coalesce(jsonb_agg(to_jsonb(c) order by issuer_cnpj,municipality,series)::text,'[]') from private.dps_counters c where environment='homologation')=current_setting('test.prod.homo_counters'),'homologation counters unchanged');
select 'PRODUCTION_ASSERTIONS='||count(*) from production_assertions;
